const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], C = tok[1];
const pre = new Array(n + 1).fill(0);
for (let i = 0; i < n; i++) pre[i + 1] = pre[i] + tok[2 + i];
const ms = [], bs = [];
let ptr = 0;
function bad(i1, i2, i3) {
  return (bs[i3] - bs[i1]) * (ms[i1] - ms[i2]) <= (bs[i2] - bs[i1]) * (ms[i1] - ms[i3]);
}
function addLine(m, b) {
  ms.push(m); bs.push(b);
  while (ms.length - ptr >= 3 && bad(ms.length - 3, ms.length - 2, ms.length - 1)) {
    ms.splice(ms.length - 2, 1);
    bs.splice(bs.length - 2, 1);
  }
}
const dp = new Array(n + 1).fill(0);
addLine(0, 0);
for (let i = 1; i <= n; i++) {
  const x = pre[i];
  if (ptr > ms.length - 1) ptr = ms.length - 1;
  while (ptr + 1 < ms.length && ms[ptr + 1] * x + bs[ptr + 1] <= ms[ptr] * x + bs[ptr]) ptr++;
  dp[i] = ms[ptr] * x + bs[ptr] + x * x + C;
  addLine(-2 * pre[i], dp[i] + pre[i] * pre[i]);
}
