import java.io.*;
import java.util.*;

public class Main {
    static long[] ms, bs;
    static int size = 0, ptr = 0;

    static boolean bad(int i1, int i2, int i3) {
        return (bs[i3] - bs[i1]) * (ms[i1] - ms[i2]) <= (bs[i2] - bs[i1]) * (ms[i1] - ms[i3]);
    }

    static void addLine(long m, long b) {
        ms[size] = m;
        bs[size] = b;
        size++;
        while (size - ptr >= 3 && bad(size - 3, size - 2, size - 1)) {
            ms[size - 2] = ms[size - 1];          // drop the middle line
            bs[size - 2] = bs[size - 1];
            size--;
        }
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        long C = (long) in.nval;
        long[] pre = new long[n + 1];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            pre[i + 1] = pre[i] + (long) in.nval;
        }
        ms = new long[n + 2];
        bs = new long[n + 2];
        long[] dp = new long[n + 1];
        addLine(0, 0);
        for (int i = 1; i <= n; i++) {
            long x = pre[i];
            if (ptr > size - 1) ptr = size - 1;
            while (ptr + 1 < size && ms[ptr + 1] * x + bs[ptr + 1] <= ms[ptr] * x + bs[ptr]) ptr++;
            dp[i] = ms[ptr] * x + bs[ptr] + x * x + C;
            addLine(-2 * pre[i], dp[i] + pre[i] * pre[i]);
        }
        System.out.println(dp[n]);
    }
}

solutions.cpp:
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
vector<ll> ms, bs;
size_t ptr_ = 0;

bool bad(int i1, int i2, int i3) {
    return (bs[i3] - bs[i1]) * (ms[i1] - ms[i2]) <= (bs[i2] - bs[i1]) * (ms[i1] - ms[i3]);
}
void add_line(ll m, ll b) {
    ms.push_back(m);
    bs.push_back(b);
    while (ms.size() - ptr_ >= 3 && bad(ms.size() - 3, ms.size() - 2, ms.size() - 1)) {
        ms.erase(ms.end() - 2);
        bs.erase(bs.end() - 2);
    }
}
int main() {
    int n;
    ll C;
    scanf("%d %lld", &n, &C);
    vector<ll> pre(n + 1, 0), dp(n + 1, 0);
    for (int i = 0; i < n; i++) {
        ll x;
        scanf("%lld", &x);
        pre[i + 1] = pre[i] + x;
    }
    add_line(0, 0);
    for (int i = 1; i <= n; i++) {
        ll x = pre[i];
        if (ptr_ > ms.size() - 1) ptr_ = ms.size() - 1;
        while (ptr_ + 1 < ms.size() && ms[ptr_ + 1] * x + bs[ptr_ + 1] <= ms[ptr_] * x + bs[ptr_]) ptr_++;
        dp[i] = ms[ptr_] * x + bs[ptr_] + x * x + C;
        add_line(-2 * pre[i], dp[i] + pre[i] * pre[i]);
    }
    printf("%lld\n", dp[n]);
    return 0;
}
